import{z as r,x as s,o as n,c as d,q as o,j as A,D as e,d as B,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"有限理性 NK","description":"","frontmatter":{"title":"有限理性 NK","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bounded-rationality-nk.md","filePath":"econ/bounded-rationality-nk.md","lastUpdated":1791413859000}'),m={name:"econ/bounded-rationality-nk.md"};function p(C,a,D,u,b,h){const t=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=o('<h1 id="有限理性-nk" tabindex="-1">有限理性 NK <a class="header-anchor" href="#有限理性-nk" aria-label="Permalink to &quot;有限理性 NK&quot;">​</a></h1><div class="epigraph"><p>把认知折扣、层级或稀疏最大化写进 NK，决定性、乘数与前瞻指引的效力都改；RE-NK 是认知成本为零的特例。</p><footer>—— Gabaix, A Behavioral New Keynesian Model, AER 2020；Woodford, Monetary Policy Analysis when Planning Horizons are Finite</footer></div><p><a href="/econ/inflation-anchoring">上一课</a>把长期信念当可破状态。本单元需要一个收束：不必每次单列粘性信息或诊断性，而是<strong>一整类</strong>偏离 RE 的 NK。本课缺口是 Gabaix 的认知折扣（及相关有限视界）如何改 IS 与菲利普斯。不重写锚定测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RE-NK：IS 完全前瞻，指引极强，BK 对泰勒原理敏感。Gabaix：人对未来的注意打认知折扣 \\(m\\lt 1\\)，有效上把 \\(\\mathbb{E}_t x_{t+1}\\) 换成 \\(m\\mathbb{E}_t x_{t+1}\\) 一类项。结果：IS 更少前瞻、财政乘数变大、指引变弱、决定性区域变化。Woodford 的有限计划视界是姐妹。缺口是给本单元一个可塞进 SW 的参数化，而不是再列五种摩擦的并集。</p><p><span class="marginnote">Gabaix, <em>AER</em> 110(8), 2020, 2271–2327。Woodford 有限视界。Angeletos and Lian 的不完全信息 NK。Farhi and Werning 的有限理性与乘数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在对数线性 NK 里替换预期算子，重算 BK 与 IRF。校准：\\(m\\) 对调查修订、对指引公告效应、对财政乘数。与 HANK 对照：有限理性 RANK 用认知折扣模仿「不那么欧拉」；HANK 用约束。两者都抬乘数，政策含义（给谁支票 vs 如何说话）不同，不要合成一个 \\(m\\)。</p>',8)),(n(),A(l,null,{default:e(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RE%5B%22RE-NK%22%5D%20--%3E%20BR%5B%22%E8%AE%A4%E7%9F%A5%E6%8A%98%E6%89%A3%20%2F%20%E6%9C%89%E9%99%90%E8%A7%86%E7%95%8C%22%5D%0A%20%20BR%20--%3E%20IS%5B%22IS%20%E6%9B%B4%E5%B0%91%E5%89%8D%E7%9E%BB%22%5D%0A%20%20BR%20--%3E%20FG%5B%22%E6%8C%87%E5%BC%95%E6%95%88%E5%8A%9B%E4%B8%8B%E9%99%8D%22%5D%0A%20%20BR%20--%3E%20MUL%5B%22%E4%B9%98%E6%95%B0%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"学习、粘性信息、疏忽、诊断性都可以视为某种有效 \\(m\\) 或额外状态；本课是方便的一参数门，不是宣布其它课作废。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：\\(m=0.8\\) 时，家庭把「明年收入将增加 5%」只当作 4% 来反应——被折扣掉的 1% 就是注意力的价钱。\\(m\\lt 1\\) 不是记性差，而是「懒得把每个未来情景都算清楚」的省事策略。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：认知折扣像戴着度数不足的眼镜看未来——大轮廓还在（利率降了就多花），细节模糊（对三年后的承诺反应迟钝）。标准 RE 则是视力 5.2，连十年后的政策路径都看得一清二楚。")],-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"机制是未来项在一阶条件里的权重下降。等价于更高的有效折扣或更短的计划。ZLB 的自我拉出更难（预期收入不够前瞻），财政相对货币更强。锚定：若认知折扣也打在长期，目标制的锚更弱，除非把 \\(\\pi^*\\) 写成单独、更凸显的状态（与疏忽的凸显一致）。",-1)),(n(),A(l,null,{default:e(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CB%5B%22%E5%A4%AE%E8%A1%8C%E5%AE%A3%E5%B8%83%E6%9C%AA%E6%9D%A5%E7%BB%B4%E6%8C%81%E4%BD%8E%E5%88%A9%E7%8E%87%22%5D%20--%3E%7C%22RE%20%E5%AE%B6%E5%BA%AD%3A%20m%3D1%2C%20%E5%85%A8%E9%A2%9D%E6%B3%A8%E6%84%8F%22%7C%20HH1%5B%22%E4%BB%8A%E5%A4%A9%E7%AB%8B%E5%8D%B3%E5%A4%9A%E6%B6%88%E8%B4%B9%22%5D%0A%20%20CB%20--%3E%7C%22%E6%9C%89%E9%99%90%E7%90%86%E6%80%A7%E5%AE%B6%E5%BA%AD%3A%20m%3D0.7%22%7C%20HH2%5B%22%E5%8F%AA%E5%93%8D%E5%BA%94%E4%B8%83%E6%88%90%2C%20%E4%B8%94%E8%B6%8A%E8%BF%9C%E8%B6%8A%E6%B7%A1%22%5D%0A%20%20HH1%20--%3E%7C%22%E4%BA%A7%E5%87%BA%E7%BC%BA%E5%8F%A3%E5%BF%AB%E9%80%9F%E6%94%B6%E6%95%9B%22%7C%20OK%5B%22%E6%8C%87%E5%BC%95%E6%8E%A5%E8%BF%91%E6%B3%B0%E5%8B%92%E5%8E%9F%E7%90%86%E7%9A%84%E5%A8%81%E5%8A%9B%22%5D%0A%20%20HH2%20--%3E%7C%22%E4%BB%8A%E5%A4%A9%E5%88%BA%E6%BF%80%E4%B8%8D%E8%B6%B3%22%7C%20WEAK%5B%22ZLB%20%E6%9B%B4%E9%9A%BE%E8%87%AA%E6%88%91%E6%8B%89%E5%87%BA%22%5D%0A%20%20HH2%20--%3E%7C%22%E8%BD%AC%E5%90%91%E5%BD%93%E4%B8%8B%E7%9A%84%E7%9B%B4%E6%8E%A5%E5%88%BA%E6%BF%80%22%7C%20FISC%5B%22%E8%B4%A2%E6%94%BF%E4%B9%98%E6%95%B0%E7%9B%B8%E5%AF%B9%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p>这张图回答的是：同一次前瞻指引，为什么在两类家庭面前效力不同。注意力折扣 \\(m\\) 打在「未来」上，离今天越远的承诺被打得越狠，于是口头指引的杠杆变短、直接发钱变得相对划算——这正是乘数与指引两条结论共同的来源。</p><p>时间不一致：有限理性的私人部门改变承诺的价值，最优规则要重算，本课不求 Ramsey。</p><p><span class="marginnote">本课仍是宏观 NK，不是心理学实验。\\(m\\) 没有唯一微观测量，必须用本单元的调查矩约束。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把行为 NK 写成交易策略。不进限价簿。金融摩擦（下一单元）是另一套放大，不要用 \\(m\\) 替代抵押约束。预期单元结束：后课默认可以在 RE、学习、信息摩擦、认知折扣中显式选择，并报告调查矩。</p><p><span class="marginnote">为什么重要：若误设 \\(m=1\\)（标准 RE），央行会高估口头指引的威力、低估直接发钱的乘数，政策组合就会偏向「说」而轻「做」。给谁支票（HANK）与如何说话（本课）是两套工具，错配会放大波动。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行为 NK：认知折扣降低前瞻性，改乘数、指引与决定性。</li><li>与 HANK 都抬乘数，机制不同。</li><li>是本单元的一参数收束，不取消分列的信息与偏差模型。</li><li>出处：Gabaix, <em>AER</em> 2020。</li></ul>',8))])}const K=r(m,[["render",p]]);export{f as __pageData,K as default};
